function countEqual012(s) {
  const seen = new Map([["0,0", 1]]);                // (c1 - c0, c2 - c1) -> times seen
  let c0 = 0, c1 = 0, c2 = 0, count = 0;
  for (const ch of s) {
    if (ch === "0") c0++; else if (ch === "1") c1++; else c2++;
    const key = (c1 - c0) + "," + (c2 - c1);          // both differences, as one key
    count += seen.get(key) ?? 0;                      // same key: equal counts in between
    seen.set(key, (seen.get(key) ?? 0) + 1);
  }
  return count;
}

long countEqual012(String s) {
    Map<String, Integer> seen = new HashMap<>();        // "c1 - c0,c2 - c1" -> times seen
    seen.put("0,0", 1);
    int c0 = 0, c1 = 0, c2 = 0;
    long count = 0;
    for (char ch : s.toCharArray()) {
        if (ch == '0') c0++; else if (ch == '1') c1++; else c2++;
        String key = (c1 - c0) + "," + (c2 - c1);        // both differences, as one key
        count += seen.getOrDefault(key, 0);              // same key: equal counts in between
        seen.merge(key, 1, Integer::sum);
    }
    return count;
}

long long countEqual012(string s) {
    unordered_map<long long, int> seen;                // packed (c1 - c0, c2 - c1) -> times seen
    seen[0] = 1;                                       // (0, 0) packs to 0
    long long c0 = 0, c1 = 0, c2 = 0, count = 0;
    for (char ch : s) {
        if (ch == '0') c0++; else if (ch == '1') c1++; else c2++;
        long long key = (c1 - c0) * 2000001 + (c2 - c1);   // each difference lies in -n..n (n <= 10^6)
        count += seen[key];                            // same key: equal counts in between
        seen[key]++;
    }
    return count;
}
